using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Funplay.Editor.Tools.Scripting;
public class ReadT018Models:IFunplayCommand{public void Execute(ExecutionContext ctx){string root="Assets/XingHaiHuiLang/Art/DungeonFamily_v1/Models";var paths=AssetDatabase.FindAssets("t:Model",new[]{root}).Select(AssetDatabase.GUIDToAssetPath).ToArray();ctx.ReturnValue=new{scene=EditorSceneManager.GetActiveScene().path,dirty=EditorSceneManager.GetActiveScene().isDirty,models=paths.Select(p=>{var g=AssetDatabase.LoadAssetAtPath<GameObject>(p);if(g==null)throw new Exception(p);return new{name=g.name,path=p,q=new[]{g.transform.localRotation.x,g.transform.localRotation.y,g.transform.localRotation.z,g.transform.localRotation.w},scale=new[]{g.transform.localScale.x,g.transform.localScale.y,g.transform.localScale.z},bounds=g.GetComponentsInChildren<Renderer>().Select(r=>new{min=new[]{r.bounds.min.x,r.bounds.min.y,r.bounds.min.z},max=new[]{r.bounds.max.x,r.bounds.max.y,r.bounds.max.z}}).ToArray()};}).ToArray()};}}
